"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        <span className="truncate">{item.title}</span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
function AppHeader({
  breadcrumb,
  showSettings,
}: {
  breadcrumb: string
  showSettings: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>{breadcrumb}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        <Button size="sm" variant="outline">
          <DeveloperDocsIcon />
          Developer Doc
        </Button>
        {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
        {showSettings ? (
          <Button aria-label="Global settings" size="icon-sm" variant="outline">
            <SettingsIcon />
          </Button>
        ) : null}
        {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
        <div className="flex items-center">
          <Separator className="mx-1 h-4" orientation="vertical" />
        </div>
        {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
        <Avatar className="size-7 rounded-lg after:rounded-lg">
          <AvatarFallback className="rounded-lg">TA</AvatarFallback>
        </Avatar>
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Page label in the breadcrumb; defaults to `active`. */
  breadcrumb?: string
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    <SidebarProvider className="min-h-0 flex-1">
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="text-muted-foreground" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          breadcrumb={breadcrumb ?? active}
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import { SCENARIO_NAME, type RetryConfig } from "@/lib/call-retry-data"
import { RetrySettingsCard } from "@/components/call-retry/retry-settings-card"

/**
 * The same card, seen from a trigger source that inherits it.
 *
 * The inherited state is the one carrying the design risk. Greyed fields read
 * as broken rather than as following the scenario, and the usual escape is to
 * press Override so the form starts working — which is how a batch ends up with
 * its own copy of settings nobody meant to fork. Naming the scenario in the
 * description makes inheriting a state you can read instead of one you flee.
 *
 * So every control stays on screen and every control is dead, Save included.
 * No banner, no explainer, and no description that swaps under a field: the
 * switch that turns editing on is in this card's own header, and a panel of
 * greyed controls under it already says the rest.
 */
export function BatchRetry({
  onOverriddenChange,
  overridden,
  scenarioConfig,
}: {
  onOverriddenChange: (overridden: boolean) => void
  overridden: boolean
  scenarioConfig: RetryConfig
}) {
  /** The batch's own copy, which only exists while the override is on. */
  const [draft, setDraft] = React.useState<RetryConfig>(scenarioConfig)

  return (
    <RetrySettingsCard
      disabled={!overridden}
      onChange={setDraft}
      onSave={() => {
        toast.success("Retry settings saved")
      }}
      /* One row, on the muted inset the house uses in place of a nested card.
         The switch, the words that label it, and the sentence saying which way
         it is currently pointing are one object — which is what it stopped
         being when the switch sat in the header and the sentence sat under the
         title. It leads the fields because it decides whose fields they are. */
      scope={
        <Item variant="muted">
          <ItemContent>
            <ItemTitle>
              <Label htmlFor="batch-override">Override scenario</Label>
            </ItemTitle>
            <ItemDescription>
              {overridden
                ? `This batch has its own retry settings. Changes to ${SCENARIO_NAME} no longer reach it.`
                : `Following the ${SCENARIO_NAME} scenario. Change its retry settings and this batch follows.`}
            </ItemDescription>
          </ItemContent>
          <ItemActions>
            <Switch
              checked={overridden}
              id="batch-override"
              onCheckedChange={(next) => {
                // Switching on seeds from the scenario; switching off discards
                // whatever the batch had, which is what "inherit" means.
                if (next) setDraft({ ...scenarioConfig })
                onOverriddenChange(next)
              }}
            />
          </ItemActions>
        </Item>
      }
      value={overridden ? draft : scenarioConfig}
    />
  )
}

"use client"

import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import {
  ATTEMPTS_MAX,
  ATTEMPTS_MIN,
  hasRetryErrors,
  retryConfigErrors,
  TIMEZONES,
  type RetryConfig,
} from "@/lib/call-retry-data"
import { TimeOfDayInput } from "@/components/call-retry/time-of-day-field"
import { WaitDurationField } from "@/components/call-retry/wait-duration-field"

/**
 * The retry configuration, as one card.
 *
 * Both surfaces render this exact component. A source overriding the scenario
 * is only checkable if it is the same fields, in the same order, with the same
 * bounds — a differently-shaped override panel is a second design the reader
 * has to reconcile by hand.
 *
 * **One column, one alignment axis.** The controls here are deliberately
 * unlike each other — six chips, a bare number, a three-part duration, two
 * three-part times, two selects — and side-by-side columns gave each pair its
 * own split, so the card had three different mid-points and no two controls
 * began at the same place. Everything now hangs off one left edge, in the
 * order a reader asks the questions: which calls, how many tries, how far
 * apart, when it may dial, how hard it may push, how it ends.
 *
 * Every field explains itself inline where it needs explaining, and no field
 * carries an (i). One explanation language per screen.
 */
export function RetrySettingsCard({
  description,
  disabled = false,
  onChange,
  onSave,
  scope,
  value,
}: {
  /** Omitted where the `scope` row already says where the policy comes from. */
  description?: string
  /** The scope is inheriting: every control stays, and every control is dead. */
  disabled?: boolean
  onChange: (value: RetryConfig) => void
  onSave: () => void
  /**
   * The inheritance control, on a trigger source. It renders above the fields
   * rather than in the header: it decides whose policy the whole card shows, so
   * it sits over what it governs instead of competing with the gate for the
   * header's end edge — where it read as a second, unrelated switch and left
   * its own label stranded between the two.
   */
  scope?: React.ReactNode
  value: RetryConfig
}) {
  const errors = retryConfigErrors(value)
  /** A field is editable only if the scope owns the policy and the gate is on. */
  const fieldsDisabled = disabled || !value.enabled

  function update(patch: Partial<RetryConfig>) {
    onChange({ ...value, ...patch })
  }

  return (
    <Card>
      {/* The gate lives on the title row, not under it. As a row of its own it
          was a label reading "Retry calls" directly beneath a title reading
          "Call retry" — the same three words twice — and a whole line spent on
          one binary. On the title row the switch needs no label at all: the
          title is its label.

          It sits at the card's end edge, where a card-level control is looked
          for, and it is the only control in the header on either surface — the
          inheritance switch that used to share this row now leads the content
          instead. Two switches on one row put "Override scenario" between them,
          labelling neither.

          A bare switch is only unlabelled where the title says what it turns
          off. It does here. */}
      <CardHeader className="mb-2">
        <div className="flex w-full items-center justify-between gap-3">
          <CardTitle>Call retry</CardTitle>
          <Switch
            aria-label="Retry calls"
            checked={value.enabled}
            disabled={disabled}
            id="retry-enabled"
            onCheckedChange={(checked) => {
              update({ enabled: checked })
            }}
          />
        </div>
        {description ? <CardDescription>{description}</CardDescription> : null}
      </CardHeader>

      {/* Retry off greys the fields rather than removing them, so the reader
          can still see what the policy was before it was switched off — and so
          the card does not change height under the hand that flipped it.

          Same read-only language as an inheriting source: every control stays,
          every control is dead. Two ways to say "you cannot edit this" would be
          two things to learn. `retryConfigErrors` already returns nothing while
          disabled, so no greyed field carries a red message and Save stays
          reachable — switching retry off is itself a change worth saving. */}
      <CardContent>
        {scope ? <div className="mb-6">{scope}</div> : null}

        {/* One rhythm, no headings. Banding the six fields 32px apart in pairs
            and 16px within a pair gave the column two spacings to read, and the
            pairs it drew — schedule, then limits — were not a difference any
            reader was asking about. One 24px step between every field, and the
            same step under the header, makes the card a single list. Six
            legends over six fields would be a heading each, which is the thing
            this repo deletes. */}
        <FieldGroup className="gap-6">
          <Field data-disabled={fieldsDisabled || undefined}>
            <FieldLabel htmlFor="retry-attempts">Retry attempts</FieldLabel>
            <Input
              /* One width for every quantity box in the column, so the
                   three of them share a right edge instead of stepping. */
              className="max-w-32"
              disabled={fieldsDisabled}
              id="retry-attempts"
              max={ATTEMPTS_MAX}
              min={ATTEMPTS_MIN}
              onChange={(event) => {
                const next = Number(event.target.value)
                if (Number.isNaN(next)) return
                update({
                  attempts: Math.min(
                    Math.max(next, ATTEMPTS_MIN),
                    ATTEMPTS_MAX,
                  ),
                })
              }}
              type="number"
              value={value.attempts}
            />
          </Field>

          <WaitDurationField
            description="Measured from the end of the previous call."
            disabled={fieldsDisabled}
            error={errors.wait}
            id="retry-wait"
            label="Wait between retries"
            onChange={(wait) => {
              update({ wait })
            }}
            value={value.wait}
          />

          {/* The window is one value, so its two ends sit on one line with
                the word that joins them — "9:00 AM to 8:00 PM" — rather than
                as two separately-labelled fields the reader has to pair up.

                A FieldSet with a legend would have been the semantic wrapper
                for the window and its timezone, but `FieldLegend` carries no
                disabled hook, so on an inheriting source it stayed black
                while every other label greyed. One field per row, no
                exceptions — the timezone reads as the window's anyway, sitting
                directly under it. */}
          <Field
            data-disabled={fieldsDisabled || undefined}
            data-invalid={errors.window !== null || undefined}
          >
            <FieldLabel htmlFor="retry-window-start-hour">
              Retry window
            </FieldLabel>
            <div className="flex flex-wrap items-center gap-3">
              <TimeOfDayInput
                disabled={fieldsDisabled}
                id="retry-window-start"
                invalid={errors.window !== null}
                label="From"
                onChange={(windowStart) => {
                  update({ windowStart })
                }}
                value={value.windowStart}
              />

              <span className="text-sm text-muted-foreground">to</span>

              <TimeOfDayInput
                disabled={fieldsDisabled}
                id="retry-window-end"
                invalid={errors.window !== null}
                label="To"
                onChange={(windowEnd) => {
                  update({ windowEnd })
                }}
                value={value.windowEnd}
              />

              <span className="text-sm text-muted-foreground">in</span>

              <Select
                disabled={fieldsDisabled}
                onValueChange={(timezone) => {
                  update({ timezone })
                }}
                value={value.timezone}
              >
                <SelectTrigger
                  aria-label="Timezone"
                  className="max-w-48"
                  id="retry-timezone"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {TIMEZONES.map((zone) => (
                    <SelectItem key={zone} value={zone}>
                      {zone}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <FieldError>{errors.window}</FieldError>
          </Field>
        </FieldGroup>
      </CardContent>

      <CardFooter className="justify-end border-t">
        <Button disabled={disabled || hasRetryErrors(errors)} onClick={onSave}>
          Save retry settings
        </Button>
      </CardFooter>
    </Card>
  )
}

"use client"

import * as React from "react"
import { toast } from "sonner"

import type { RetryConfig } from "@/lib/call-retry-data"
import { RetrySettingsCard } from "@/components/call-retry/retry-settings-card"
import { SaveConfirmDialog } from "@/components/call-retry/save-confirm-dialog"

/**
 * The scenario's retry configuration — the default every trigger source reads.
 *
 * Saving is where the "global" in the PRD's title becomes visible: this is the
 * one screen whose Save moves calls that are already waiting, on sources nobody
 * is looking at. So it is the one screen that confirms before it does.
 */
export function ScenarioRetry({
  config,
  onConfigChange,
  queued,
  scheduled,
}: {
  config: RetryConfig
  onConfigChange: (config: RetryConfig) => void
  queued: number
  scheduled: number
}) {
  const [confirming, setConfirming] = React.useState(false)

  return (
    <>
      <RetrySettingsCard
        description="Every trigger source uses these settings unless it overrides them."
        onChange={onConfigChange}
        onSave={() => {
          // Nothing is waiting, so there is nothing to confirm. A dialog whose
          // whole content is two counts has nothing to say when both are zero.
          if (queued + scheduled === 0) {
            toast.success("Retry settings saved")
            return
          }
          setConfirming(true)
        }}
        value={config}
      />

      <SaveConfirmDialog
        onConfirm={() => {
          toast.success("Retry settings saved")
        }}
        onOpenChange={setConfirming}
        open={confirming}
        queued={queued}
        scheduled={scheduled}
      />
    </>
  )
}

